package e2e
import("encoding/json";"fmt";"net/http";"os";"testing";"time")
func TestMediaControlEnvironmentGrantE2E(t *testing.T){a,ctrl:=os.Getenv("MEDIA_AUTH_ADDR"),os.Getenv("MEDIA_CONTROL_ADDR");if a==""||ctrl==""{t.Skip("MEDIA_AUTH_ADDR and MEDIA_CONTROL_ADDR are required")};c:=httpClient(t);login(t,c,a,envOr("MEDIA_AUTH_E2E_USER","smoke"),envOr("MEDIA_AUTH_E2E_PASS","smoke123"));s,b:=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/runtime-environments",map[string]string{"name":fmt.Sprintf("grant-env-%d",time.Now().UnixNano()),"endpoint":"http://runtime-controller","capacity_json":"{}"});if s!=http.StatusCreated{t.Fatalf("environment: %d %s",s,b)};var env struct{ID string};json.Unmarshal(b,&env);s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/runtime-environments/"+env.ID+"/grants",map[string]string{"subject_id":"user-2","subject_type":"user","permission":"use"});if s!=http.StatusCreated{t.Fatalf("grant: %d %s",s,b)};var g struct{ID string;Status string};json.Unmarshal(b,&g);if g.ID==""||g.Status!="active"{t.Fatalf("unexpected grant: %+v",g)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/runtime-environments/"+env.ID+"/grants/"+g.ID+"/revoke",map[string]any{});if s!=http.StatusOK||!jsonContains(b,`"status":"revoked"`){t.Fatalf("revoke: %d %s",s,b)}}
